import java.util.Set;
import java.util.HashSet;
import java.util.TreeSet;
import java.util.List;

class Main {
    public static void main(String[] args) throws Exception {
        Set<Integer> rolls = new HashSet<>(List.of(22, 17, 22));
        System.out.println(rolls.size());
        System.out.println(new TreeSet<>(rolls));
    }
}

import java.util.Map;
import java.util.HashMap;
import java.util.TreeMap;
import java.util.List;

class Main {
    public static void main(String[] args) throws Exception {
        Map<String, Integer> counts = new HashMap<>();
        for (String word : List.of("book", "pen", "book")) {
            counts.put(word, counts.getOrDefault(word, 0) + 1);
        }
        for (Map.Entry<String, Integer> entry : new TreeMap<>(counts).entrySet()) {
            System.out.println(entry.getKey() + " " + entry.getValue());
        }
    }
}
